<script setup>
import {reactive,watch,ref,computed} from 'vue'
import {useUnsavedForm} from '../../composables/useUnsavedForm'
import {RouterLink} from 'vue-router'
import {profileApi} from '../../api/customers.api'
import {useApiState,useApiMutation} from '../../composables/useApiState'
import {useAuthStore} from '../../stores/auth'
import ApiFeedback from '../../components/admin/catalog/ApiFeedback.vue'
import SiteIcon from '../../components/site/SiteIcon.vue'

const state=useApiState(),mutation=useApiMutation(),auth=useAuthStore(),form=reactive({name:'',email:''}),notice=ref('')
function load(){return state.run(signal=>profileApi.show(signal))}
const dirty=computed(()=>state.data.value&& (form.name!==state.data.value.name||form.email!==(state.data.value.email||'')))
const initial=computed(()=>(state.data.value?.name||'').trim().charAt(0)||'ش')
const statistics=computed(()=>state.data.value?.statistics)
function reset(){if(state.data.value)Object.assign(form,{name:state.data.value.name,email:state.data.value.email||''});mutation.error.value=null;notice.value=''}
useUnsavedForm(dirty,mutation.busy)
watch(state.data,value=>{if(value)Object.assign(form,{name:value.name,email:value.email||''})})
watch([()=>form.name,()=>form.email],()=>{if(dirty.value)notice.value=''}, {flush:'sync'})
async function save(){if(!dirty.value||mutation.busy.value)return;notice.value='';const result=await mutation.run(()=>profileApi.update({name:form.name,email:form.email||null}));if(result.ok){state.data.value=result.data;auth.user={...auth.user,name:result.data.name,email:result.data.email};notice.value='تم حفظ بيانات الحساب.'}}
async function claim(){if(dirty.value||mutation.busy.value)return;notice.value='';const result=await mutation.run(()=>profileApi.claim());if(result.ok){await load();notice.value=result.data.claimed_orders?'تمت إضافة '+result.data.claimed_orders+' من طلباتك السابقة إلى حسابك.':'لا توجد طلبات سابقة جديدة لربطها بحسابك.'}}
load()
</script>
<template>
 <main id="main" class="container account-main">
  <header class="account-heading"><div><span class="section-kicker">أهلًا بك في شيشلي</span><h1>حسابي</h1><p>بياناتك وطلباتك وعناوينك، في مكان واحد.</p></div><RouterLink class="account-menu-link" to="/menu">العودة للمنيو <SiteIcon name="arrow-left"/></RouterLink></header>
  <ApiFeedback variant="detail" :loading="state.loading.value" :error="state.error.value" error-title="تعذر تحميل حسابك" @retry="load"/>
  <template v-if="state.data.value">
   <section class="account-welcome" aria-label="ملخص حسابك"><div class="account-identity"><span class="account-avatar" aria-hidden="true">{{ initial }}</span><div><span class="account-welcome-label">سعداء بوجودك معنا</span><h2>{{ state.data.value.name }}</h2><p v-if="state.data.value.phone" dir="ltr">{{ state.data.value.phone }}</p></div></div><div v-if="statistics" class="account-statistics"><div><strong>{{ statistics.orders_count }}</strong><span>طلباتي</span></div><div><strong>{{ statistics.completed_orders_count }}</strong><span>طلبات مكتملة</span></div></div></section>
   <nav class="account-shortcuts" aria-label="روابط حسابي"><RouterLink to="/account/orders"><span class="account-shortcut-icon"><SiteIcon name="shopping-bag"/></span><div><strong>طلباتي</strong><span>تابع طلبك واطّلع على طلباتك</span></div><SiteIcon name="arrow-left"/></RouterLink><RouterLink to="/account/addresses"><span class="account-shortcut-icon"><SiteIcon name="map-pin"/></span><div><strong>عناويني</strong><span>عناوينك المحفوظة للتوصيل</span></div><SiteIcon name="arrow-left"/></RouterLink></nav>
   <div v-if="notice" class="account-notice" role="status"><SiteIcon name="badge-check"/><p>{{ notice }}</p></div>
   <div v-if="mutation.error.value" class="account-error" role="alert"><p>{{ mutation.error.value.message }}</p></div>
   <div class="account-grid">
    <section class="account-card account-details" aria-labelledby="account-details-title"><div class="account-card-heading"><span class="account-shortcut-icon"><SiteIcon name="user-round"/></span><div><h2 id="account-details-title">بيانات الحساب</h2><p>حدّث اسمك وبريدك الإلكتروني بسهولة.</p></div></div>
     <form @submit.prevent="save"><div class="account-fields"><div class="auth-field"><label for="profile-name">الاسم</label><input id="profile-name" v-model="form.name" autocomplete="name" required maxlength="150" :disabled="mutation.busy.value" :aria-invalid="Boolean(mutation.error.value?.errors.name)" :aria-describedby="mutation.error.value?.errors.name?'profile-name-error':undefined"><small v-if="mutation.error.value?.errors.name" id="profile-name-error" role="alert">{{ mutation.error.value.errors.name.join(' ') }}</small></div><div class="auth-field"><label for="profile-email">البريد الإلكتروني <span class="account-optional">اختياري</span></label><input id="profile-email" v-model="form.email" type="email" autocomplete="email" dir="ltr" inputmode="email" placeholder="name@example.com" maxlength="255" :disabled="mutation.busy.value" :aria-invalid="Boolean(mutation.error.value?.errors.email)" :aria-describedby="mutation.error.value?.errors.email?'profile-email-error':undefined"><small v-if="mutation.error.value?.errors.email" id="profile-email-error" role="alert">{{ mutation.error.value.errors.email.join(' ') }}</small></div></div>
      <div class="account-phone"><span class="account-shortcut-icon"><SiteIcon name="phone"/></span><div><span>رقم الجوال</span><strong><bdi>{{ state.data.value.phone||'لم يُضف رقم جوال' }}</bdi></strong><small>رقم الجوال المرتبط بحسابك.</small></div></div>
      <div class="account-save-actions"><button type="submit" class="button button-primary" :disabled="mutation.busy.value||!dirty">{{ mutation.busy.value?'جارٍ الحفظ…':'حفظ الحساب' }}</button><button v-if="dirty" type="button" class="text-button" :disabled="mutation.busy.value" @click="reset">تراجع عن التعديل</button></div>
     </form>
    </section>
    <aside class="account-side"><section class="account-card" aria-labelledby="account-address-title"><div class="account-card-heading"><span class="account-shortcut-icon"><SiteIcon name="map-pin"/></span><h2 id="account-address-title">عنوان التوصيل</h2></div><template v-if="state.data.value.default_address"><strong class="account-address-label">{{ state.data.value.default_address.label||'عنوانك الافتراضي' }}</strong><p>{{ [state.data.value.default_address.city,state.data.value.default_address.district,state.data.value.default_address.street].filter(Boolean).join('، ') }}</p></template><p v-else>احفظ عنوانك لتأكيد طلبك القادم بسهولة.</p><RouterLink class="account-card-link" to="/account/addresses">{{ state.data.value.default_address?'إدارة العناوين':'إضافة عنوان' }} <SiteIcon name="arrow-left"/></RouterLink></section>
     <section v-if="state.data.value.phone_verified" class="account-card" aria-labelledby="account-claim-title"><div class="account-card-heading"><span class="account-shortcut-icon"><SiteIcon name="refresh"/></span><h2 id="account-claim-title">طلباتك السابقة</h2></div><p>طلبت سابقًا دون تسجيل الدخول؟ أضف الطلبات المرتبطة برقم جوالك إلى حسابك.</p><button type="button" class="button account-claim" :disabled="mutation.busy.value||dirty" @click="claim">ربط الطلبات</button><small v-if="dirty">احفظ تعديلاتك أولًا أو تراجع عنها.</small></section>
    </aside>
   </div>
  </template>
 </main>
</template>
<style scoped>
.account-main{padding-block:36px 64px;max-width:1120px}
.account-heading{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:24px;flex-wrap:wrap}.account-heading h1{font-size:30px;margin-block:4px}.account-heading p{color:var(--muted);font-size:14px}.account-menu-link,.account-card-link{display:inline-flex;align-items:center;gap:9px;color:var(--primary);font-size:13px;font-weight:700}.account-menu-link .icon,.account-card-link .icon{width:17px}
.account-welcome{background:var(--primary-dark);color:var(--cream);border:1px solid #c9963b33;border-radius:18px;padding:26px 28px;display:flex;align-items:center;justify-content:space-between;gap:28px}.account-identity{display:flex;align-items:center;gap:16px;min-width:0}.account-identity>div{min-width:0}.account-avatar{display:grid;place-items:center;width:64px;height:64px;flex-shrink:0;border:1px solid #c9963b66;background:#c9963b18;border-radius:50%;font-size:30px;color:#edc88e;font-weight:700}.account-welcome-label{font-size:12px;color:#e1b97b}.account-identity h2{font-size:23px;overflow-wrap:anywhere;line-height:1.5}.account-identity p{font-size:13px;color:#e7d3cd;text-align:right;margin-top:5px}.account-statistics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;text-align:center;flex-shrink:0}.account-statistics>div{display:flex;flex-direction:column;gap:4px;min-width:0}.account-statistics strong{font-size:21px;overflow-wrap:anywhere}.account-statistics span{font-size:11px;color:#e7d3cd}
.account-shortcuts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin-block:20px 24px}.account-shortcuts>a{display:flex;align-items:center;gap:14px;padding:20px;border:1px solid var(--border);border-radius:14px;background:#fff;transition:border-color .2s,background .2s}.account-shortcuts>a:hover{border-color:var(--gold);background:#fffdf9}.account-shortcuts>a>div{flex:1;min-width:0}.account-shortcuts strong{display:block;font-size:17px}.account-shortcuts div>span{display:block;font-size:12px;color:var(--muted);margin-top:3px}.account-shortcuts>a>.icon{width:18px;color:var(--primary)}.account-shortcut-icon{display:grid;place-items:center;width:42px;height:42px;flex-shrink:0;border-radius:12px;background:#5a172508;color:var(--primary)}
.account-grid{display:grid;grid-template-columns:minmax(0,1fr) 310px;gap:20px;align-items:start}.account-card{padding:24px;background:#fff;border:1px solid var(--border);border-radius:16px;min-width:0}.account-card-heading{display:flex;align-items:center;gap:12px;margin-bottom:22px}.account-card-heading h2{font-size:18px}.account-card-heading p,.account-side p{font-size:13px;color:var(--muted);margin-top:5px;line-height:1.8;overflow-wrap:anywhere}.account-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.account-fields .auth-field{min-width:0;margin:0}.account-fields input{width:100%;min-width:0;background:var(--cream);border-radius:10px}.account-fields input[aria-invalid=true]{border-color:var(--secondary)}.account-fields small{color:var(--secondary)}.account-optional{font-size:11px;font-weight:400;color:var(--muted);margin-inline-start:6px}.account-phone{display:flex;gap:12px;align-items:center;margin-top:22px;padding:16px;border:1px solid var(--border);border-radius:12px;background:var(--cream)}.account-phone>div{min-width:0}.account-phone span:not(.account-shortcut-icon){font-size:12px;color:var(--muted)}.account-phone strong,.account-phone small{display:block;overflow-wrap:anywhere}.account-phone strong{font-size:15px}.account-phone small{font-size:11px;color:var(--muted);margin-top:3px}.account-save-actions{display:flex;align-items:center;flex-wrap:wrap;gap:16px;border-top:1px solid var(--border);padding-top:20px;margin-top:24px}.account-save-actions .button{min-height:44px;padding-inline:26px}.account-side{display:grid;gap:18px}.account-side .account-card-heading{margin-bottom:14px}.account-address-label{font-size:14px;overflow-wrap:anywhere}.account-card-link{margin-top:18px}.account-claim{margin-top:18px;width:100%;min-height:44px}.account-side small{display:block;color:var(--muted);font-size:11px;margin-top:8px}.account-notice,.account-error{padding:14px 18px;border-radius:12px;margin-bottom:20px;font-size:13px}.account-notice{display:flex;align-items:center;gap:10px;background:#edf5eb;border:1px solid #cbdcc7;color:#355d30}.account-error{background:#fff0f0;border:1px solid #efd2d2;color:var(--primary)}
@media(max-width:900px){.account-grid{grid-template-columns:minmax(0,1fr)}.account-side{grid-template-columns:repeat(2,minmax(0,1fr))}.account-welcome{align-items:flex-start;flex-direction:column;gap:22px}.account-statistics{width:100%;border-top:1px solid #ffffff20;padding-top:18px}}
@media(max-width:600px){.account-main{padding-block:24px 40px}.account-heading{gap:12px}.account-heading h1{font-size:26px}.account-welcome{padding:20px;border-radius:14px}.account-avatar{width:54px;height:54px;font-size:26px}.account-identity h2{font-size:21px}.account-statistics{gap:8px}.account-statistics strong{font-size:18px}.account-statistics span{font-size:10px}.account-shortcuts{gap:10px;margin-block:16px 20px}.account-shortcuts>a{padding:15px 12px;gap:10px;align-items:flex-start;flex-direction:column}.account-shortcuts>a>.icon{display:none}.account-shortcuts strong{font-size:15px}.account-shortcuts div>span{font-size:11px}.account-card{padding:20px}.account-card-heading h2{font-size:17px}.account-fields,.account-side{grid-template-columns:minmax(0,1fr)}.account-fields{gap:18px}.account-save-actions .button{flex:1}.account-notice{align-items:flex-start}}
</style>
